/**
 * Verified per-state licensing facts for the 51 state license guides
 * (/blog/np-license-<state>, generated by lib/blog-license-guides.ts).
 *
 * WHY THIS FILE EXISTS (indexing audit CQ-03, owner decision 2026-09-28):
 * the guides share one template and, until now, answered every fee, renewal,
 * continuing-education and processing-time question with a board link. They
 * stay live and linked, but each one renders "noindex, follow" and stays out
 * of the sitemap until its state carries the verified facts below. A guide
 * becomes indexable on its own, state by state, the moment
 * isLicenseGuideIndexable(stateCode) turns true: the page robots tag and the
 * sitemap both read that one predicate, so they cannot drift apart.
 *
 * HOW TO FILL AN ENTRY (research pass):
 *   - Key: the two-letter postal code, DC included ('TX', 'DC'). The entry's
 *     stateCode repeats the key.
 *   - Add a fact only after reading it at sourceUrl on checkedOn. Prefer the
 *     state board of nursing or the statute or rule itself. sourceUrl is the
 *     exact https page the value was read from, with any parentheses or
 *     spaces percent-encoded (%28, %29, %20) so the markdown link can carry
 *     it; a page served only over http needs an https copy of the same text.
 *     sourceName names that page's publisher as the page names itself (e.g.
 *     'Texas Board of Nursing'), never a capitalised tier label such as
 *     'Full Practice Authority' beside a state AANP classifies otherwise.
 *   - value is the fact in plain professional English, as the source states
 *     it: no en dash, em dash or spaced hyphen, ranges read "to", no pipe
 *     character, one line. Quote a fee exactly as the board prints it.
 *   - checkedOn is the ISO date (YYYY-MM-DD) the value was read at the source.
 *   - Leave a field null when the source does not state it. Never estimate.
 *   - Set verified to true only when a second person has re-read every
 *     non-null value at its source. verified plus initialFee, renewalCycle and
 *     ceRequirement is what makes a guide indexable.
 * Every entry is checked by tests/regressions/license-guide-facts.test.ts
 * (well-formed values, https sources, real dates, house style).
 *
 * Relative imports only (none today): scripts/sync-blog-to-db.ts loads the
 * guide generator, and through it this file, under plain tsx.
 */

/** One sourced, dated fact about a state's APRN licensure. */
export interface LicenseGuideFact {
    /** The fact as the source states it, in plain English. */
    value: string;
    /** The https page the value was read from. */
    sourceUrl: string;
    /** Publisher of that page, e.g. 'Texas Board of Nursing'. */
    sourceName: string;
    /** ISO date (YYYY-MM-DD) the value was read at sourceUrl. */
    checkedOn: string;
}

/** The facts a state's license guide needs before it may be indexed. */
export interface LicenseGuideStateFacts {
    /** Two-letter postal code; repeats the LICENSE_GUIDE_FACTS key. */
    stateCode: string;
    /** Initial APRN (or NP) application or licensure fee. */
    initialFee: LicenseGuideFact | null;
    /** How often the APRN license renews. */
    renewalCycle: LicenseGuideFact | null;
    /** Continuing education required for renewal, pharmacology hours included. */
    ceRequirement: LicenseGuideFact | null;
    /** Typical processing time the board publishes. */
    processingTime: LicenseGuideFact | null;
    /** How to apply (online portal, endorsement route, required verifications). */
    applicationRoute: LicenseGuideFact | null;
    /** True only once every non-null value was re-read at its source by a second person. */
    verified: boolean;
}

