/**
 * True only when the state's facts are verified and its initial fee, renewal
 * cycle and continuing education requirement are all present. Drives the
 * guide's robots tag and its sitemap entry.
 *
 * `facts` defaults to LICENSE_GUIDE_FACTS; tests pass a sample table.
 */
export function isLicenseGuideIndexable(
    stateCode: string,
    facts: Readonly<Record<string, LicenseGuideStateFacts>> = LICENSE_GUIDE_FACTS,
): boolean {
    const entry = facts[stateCode.trim().toUpperCase()];
    if (!entry || entry.verified !== true) return false;
    return entry.initialFee !== null && entry.renewalCycle !== null && entry.ceRequirement !== null;
}
